test('REQ-2-3: REQ-2-3: Grant Repository Access to People and Teams - Scenario 1', async ({ page }) => {
  // GIVEN: repo-admin has Admin permission on acme-docs; frontend-team has no direct
  // access grant on it.
  await signIn(page, 'repo-admin@example.test');
  await openRepository(page, 'acme-docs');

  // WHEN: open Settings -> Manage access -> Add people or teams.
  await page.getByRole('link', { name: 'Settings', exact: true }).click();
  await page.getByRole('link', { name: 'Manage access', exact: true }).click();
  await page.getByText('Add people or teams', { exact: true }).click();

  // The global header search and the picker's Search textbox share the label; the
  // picker is the later control on the page.
  await page.getByLabel('Search', { exact: true }).last().fill('frontend-team');
  await page.getByRole('option', { name: 'frontend-team', exact: true }).click();
  await chooseOption(page.getByLabel('Role', { exact: true }).last(), 'Write');
  await page.getByRole('button', { name: 'Add', exact: true }).click();

  // THEN: the access list shows the team with Write access.
  const accessRow = page.getByRole('row', { name: /frontend-team/ });
  await expect(accessRow).toHaveCount(1);
  await expect(accessRow.getByText('frontend-team', { exact: true })).toBeVisible();
  await expect(accessRow.getByText('Write', { exact: true })).toBeVisible();

  // THEN: the grant survives a reload of Manage access.
  await page.reload();
  await expect(page.getByRole('row', { name: /frontend-team/ })).toBeVisible();
});

test('REQ-2-3#2: REQ-2-3: Grant Repository Access to People and Teams - Scenario 2', async ({ page }) => {
  // GIVEN: repo-admin has Admin permission on acme-docs; access-role-team already has
  // exactly one direct Write grant on it.
  await signIn(page, 'repo-admin@example.test');
  await openRepository(page, 'acme-docs');

  // WHEN: change the existing grant from Write to Read.
  await page.getByRole('link', { name: 'Settings', exact: true }).click();
  await page.getByRole('link', { name: 'Manage access', exact: true }).click();

  const row = page.getByRole('row', { name: /access-role-team/ });
  await expect(row.getByText('Write', { exact: true })).toBeVisible();
  await chooseOption(row.getByLabel('Role', { exact: true }), 'Read');
  await row.getByRole('button', { name: 'Save', exact: true }).click();

  // THEN: exactly one row for the team remains and it displays Read.
  await page.reload();
  const reloadedRow = page.getByRole('row', { name: /access-role-team/ });
  await expect(reloadedRow).toHaveCount(1);
  await expect(reloadedRow.getByText('Read', { exact: true })).toBeVisible();
});

// Added by the suite runner: a helper that uses `page` without taking it as a parameter sees the running test's page.
require('@playwright/test').test.beforeEach(async ({ page }) => { globalThis.page = page; });

test('REQ-4-2-3: Search Code Within a Repository - Scenario 3', async ({ page }) => {
  await page.goto('/');
  await openCodePage(page, 'acme-docs');

  await repositorySearch(page, 'search flow');
  await openCodeResults(page);
  await page.getByRole('link', { name: 'README.md', exact: true }).first().click();

  await expect(page.getByText('search flow').first()).toBeVisible();

  await page.reload();
  await expect(page.getByText('search flow').first()).toBeVisible();
  await expect(page.getByRole('link', { name: 'README.md', exact: true }).first()).toBeVisible();
});

test('REQ-6-1: REQ-6-1: Protect Branches with Review and Status-Check Requirements - Scenario 1', async ({ page }) => {
  await signIn(page, 'protection-admin');
  await openRepo(page, 'branch-protection-demo');

  await clickNamed(page, 'Settings');
  await clickNamed(page, 'Branches');

  await clickNamed(page, 'Add branch protection rule');
  await page.getByLabel('Branch name pattern', { exact: true }).fill('main');
  await page.getByLabel('Require 1 approval', { exact: true }).check();
  await page.getByLabel('Require status check test', { exact: true }).check();
  if (!(await clickNamed(page, 'Create'))) {
    await clickNamed(page, 'Save changes');
  }

  await page.reload();
  await expect(page.getByText('main', { exact: true }).first()).toBeVisible();
  await expect(page.getByText(/1 approval/i).first()).toBeVisible();
  await expect(page.getByText(/status check/i).first()).toBeVisible();
});

test('REQ-6-5: REQ-6-5: Merge an Eligible Pull Request - Scenario 1', async ({ page }) => {
  await signIn(page, 'pr-maintainer');
  await openPullRequest(page, 'acme-docs', 'Mergeable onboarding PR');

  await expect(page.getByText('Create a merge commit', { exact: true }).first()).toBeVisible();
  const method = page.getByRole('radio', { name: 'Create a merge commit', exact: true });
  if (await method.count() > 0) {
    await expect(method.first()).toBeChecked();
  }

  await clickNamed(page, 'Merge pull request');
  await clickNamed(page, 'Confirm merge');

  await expect(page.getByText('Merged', { exact: true }).first()).toBeVisible();
  await expect(page.getByText(/ago|just now/i).first()).toBeVisible();
  await expect(page.getByText(/\b[0-9a-f]{7,40}\b/).first()).toBeVisible();

  await page.reload();
  await expect(page.getByText('Merged', { exact: true }).first()).toBeVisible();

  // the merge commit is on the main branch
  await openRepo(page, 'acme-docs');
  await clickNamed(page, 'Commits');
  await expect(page.getByText(/merge/i).first()).toBeVisible();
});
